ipcRegistrations.handler:
(event, payload: unknown) => {
    const owner = attached.get(event.sender.id);
    if (owner == null) {
      // A page that is not a registered view. Nothing else in this app posts
      // on this channel, so this is either a race with teardown or something
      // that has no business here; either way there is no extension to
      // deliver it to.
      return;
    }
    if (!withinRate(event.sender.id, Date.now())) {
      return;
    }

    let size = 0;
    try {
      size = JSON.stringify(payload)?.length ?? 0;
    } catch {
      return;
    }
    if (size > MAX_VIEW_MESSAGE_BYTES) {
      console.warn("[extension] dropping a " + size + " byte message from " + owner.extId);
      return;
    }

    forward(owner.extId, owner.viewId, payload);
  }

async (evt, bloburl, mediapath) => {
  const result = new Promise((resolve, reject) => {
    ffmpeg.ffprobe(mediapath, (err, metadata) => {
      console.log(mediapath, metadata, bloburl);
      resolve({
        bloburl: bloburl,
        metadata: metadata,
      });
    });
  });

  return result;
}

(event, allowed: boolean) => {
  throttlingHold(event.sender, allowed === true);
  return true;
}

(_event, id: string, response: BridgeResponse) => {
    const entry = pending.get(id);
    if (entry == null) {
      // A reply that arrived after its own timeout. Dropping it is correct —
      // the caller already got an error and moved on.
      return;
    }

    pending.delete(id);
    clearTimeout(entry.timer);

    if (response?.ok) {
      entry.resolve(response.result);
    } else {
      entry.reject(new Error(response?.error ?? "Unknown editor error"));
    }
  }

